"""Hacker News — MCP server generated by Handyman.

Use these tools to browse Hacker News content: stories, comments, jobs, polls, and users. Start with one of the listing tools (top/new/best/ask/show/job stories) to get a list of item ids, then use get_item to fetch details of a specific item (including its comments via the 'kids' field, which you can resolve with further get_item calls). Use get_user for profile info on a specific username. All data is read-only and public.

Source API: https://raw.githubusercontent.com/HackerNews/API/master/README.md
Regenerate with: handyman generate https://raw.githubusercontent.com/HackerNews/API/master/README.md
"""

from typing import Annotated, Any

import httpx
from arcade_mcp_server import MCPApp

app = MCPApp(
    name='hacker_news',
    version="0.1.0",
    log_level="ERROR",
    instructions="Use these tools to browse Hacker News content: stories, comments, jobs, polls, and users. Start with one of the listing tools (top/new/best/ask/show/job stories) to get a list of item ids, then use get_item to fetch details of a specific item (including its comments via the 'kids' field, which you can resolve with further get_item calls). Use get_user for profile info on a specific username. All data is read-only and public.",
)

BASE_URL = 'https://hacker-news.firebaseio.com/v0'

# ---------------------------------------------------------------------------
# Request plumbing — the single HTTP door every tool goes through
# ---------------------------------------------------------------------------


def _request(
    method: str,
    path: str,
    params: dict[str, Any] | None = None,
    headers: dict[str, str] | None = None,
) -> Any:
    """Issue one API request and return parsed JSON, raising a readable error
    on HTTP failure so the calling agent can react."""
    all_headers = dict(_DEFAULT_HEADERS)
    all_headers.update(headers or {})
    response = httpx.request(
        method,
        BASE_URL + path,
        params=params or None,
        headers=all_headers,
        timeout=30,
        follow_redirects=True,
    )
    if response.status_code >= 400:
        raise RuntimeError(f"{method} {path} failed ({response.status_code}): {response.text[:300]}")
    return response.json()


def _dig(payload: Any, path: str) -> Any:
    """Follow a dot path into a JSON payload, failing loudly when it is absent.
    Used between chained calls, where a missing value means the chain is wrong."""
    value = payload
    for key in path.split("."):
        if not isinstance(value, dict) or key not in value:
            available = sorted(value.keys()) if isinstance(value, dict) else type(value).__name__
            raise RuntimeError(f"response missing '{path}' (at '{key}'; found: {available})")
        value = value[key]
    return value


def _prune(payload: Any, path: str) -> Any:
    """Best-effort final shaping: return the payload at a dot path, or the full
    payload when the shape drifted — a bigger answer beats a broken tool."""
    value = payload
    for key in path.split("."):
        if not isinstance(value, dict) or key not in value:
            return payload
        value = value[key]
    return value


def _as_object(value: Any) -> dict:
    """Tools always return a JSON object; non-object payloads are wrapped."""
    return value if isinstance(value, dict) else {"result": value}


_DEFAULT_HEADERS: dict[str, str] = {}


# ---------------------------------------------------------------------------
# Tools
# ---------------------------------------------------------------------------


@app.tool
def get_item(
    id: Annotated[int, "The item's unique numeric id."],
) -> Annotated[dict, 'Item object with fields like by, descendants, id, kids, score, time, title, type, url, text, parent, poll, parts, deleted, dead.']:
    """
    Fetch a single Hacker News item (story, comment, job posting, Ask HN, Show HN, or
    poll) by its numeric id. Use this to get full details of an item you already have
    the id for, including title, author, score, text, url, and child comment ids
    ('kids'). To find ids, first use one of the story-listing tools. Returns the item's
    fields, or null if the id doesn't exist or the item was deleted.
    """
    response = _request("GET", f"/item/{id}.json")
    return _as_object(response)


@app.tool
def get_user(
    username: Annotated[str, "The user's exact, case-sensitive username."],
) -> Annotated[dict, 'User object with about, created, id, karma, and submitted (list of item ids).']:
    """
    Fetch a Hacker News user's public profile by their case-sensitive username. Use this
    when you need info about a specific person (karma, account creation time, bio,
    submitted item ids). Only returns data for users with public activity; returns null
    if the user doesn't exist.
    """
    response = _request("GET", f"/user/{username}.json")
    return _as_object(response)


@app.tool
def list_top_stories(
    limit: Annotated[int, 'Maximum number of story ids to return, taken from the top of the ranked list.'] = 30,
) -> Annotated[dict, 'List of story item ids, ranked by current top placement.']:
    """
    Get the current top-ranked Hacker News stories (the front page and beyond), up to
    500 item ids ordered by rank. Use this for 'what's trending on HN right now'.
    Returns only ids; call get_item on individual ids to get titles, scores, etc. Note:
    response is large, so this tool returns only the first N ids as requested.
    """
    response = _request("GET", '/topstories.json')
    return _as_object(response)


@app.tool
def list_new_stories(
    limit: Annotated[int, 'Maximum number of story ids to return, taken from the newest end of the list.'] = 30,
) -> Annotated[dict, 'List of story item ids, newest first.']:
    """
    Get the newest Hacker News story submissions, up to 500 item ids, most recent first.
    Use this to find recently posted stories before they've accumulated votes. Returns
    only ids; call get_item on individual ids for details.
    """
    response = _request("GET", '/newstories.json')
    return _as_object(response)


@app.tool
def list_best_stories(
    limit: Annotated[int, 'Maximum number of story ids to return, taken from the top of the best-ranked list.'] = 30,
) -> Annotated[dict, 'List of story item ids, best-ranked first.']:
    """
    Get Hacker News stories currently ranked 'best' (highest quality/score over a recent
    window), as item ids. Use this when the user wants a curated set of high-quality
    recent stories rather than raw new or top-ranked ones. Returns only ids; call
    get_item on individual ids for details.
    """
    response = _request("GET", '/beststories.json')
    return _as_object(response)


@app.tool
def list_ask_hn_stories(
    limit: Annotated[int, 'Maximum number of story ids to return.'] = 30,
) -> Annotated[dict, 'List of Ask HN story item ids, most recent first.']:
    """
    Get the latest 'Ask HN' story item ids (up to 200), where users ask the Hacker News
    community a question. Use this when the user specifically wants Ask HN posts rather
    than general stories. Returns only ids; call get_item on individual ids for details.
    """
    response = _request("GET", '/askstories.json')
    return _as_object(response)


@app.tool
def list_show_hn_stories(
    limit: Annotated[int, 'Maximum number of story ids to return.'] = 30,
) -> Annotated[dict, 'List of Show HN story item ids, most recent first.']:
    """
    Get the latest 'Show HN' story item ids (up to 200), where users showcase a project.
    Use this when the user specifically wants Show HN posts. Returns only ids; call
    get_item on individual ids for details.
    """
    response = _request("GET", '/showstories.json')
    return _as_object(response)


@app.tool
def list_job_stories(
    limit: Annotated[int, 'Maximum number of job story ids to return.'] = 30,
) -> Annotated[dict, 'List of job story item ids, most recent first.']:
    """
    Get the latest job posting item ids on Hacker News (up to 200). Use this when the
    user wants job listings specifically. Returns only ids; call get_item on individual
    ids for details.
    """
    response = _request("GET", '/jobstories.json')
    return _as_object(response)


if __name__ == "__main__":
    import sys

    app.run(transport=sys.argv[1] if len(sys.argv) > 1 else "stdio")
